    "grammar": [
      {
        "title": {
          "en": "Advanced collocations for describing trends and change",
          "pt": "Colocações avançadas para descrever tendências e mudanças"
        },
        "examples": [
          {
            "en": "There has been a sharp increase in online learning enrollment.",
            "pt": "Houve um aumento acentuado nas matrículas de ensino online."
          },
          {
            "en": "The country is experiencing a gradual decline in birth rates.",
            "pt": "O país está experimentando um declínio gradual nas taxas de natalidade."
          },
          {
            "en": "The invention of the internet marked a turning point in communication.",
            "pt": "A invenção da internet marcou um ponto de virada na comunicação."
          }
        ],
        "rule": {
          "en": "Advanced collocations combine adjectives, adverbs, or nouns with other words to create specific and nuanced descriptions of changes, trends, or developments. These fixed or semi-fixed phrases are more precise and formal than general vocabulary. Common patterns include 'adjective + noun' (e.g., 'significant shift', 'dramatic rise'), 'adverb + verb' (e.g., 'rapidly evolve', 'steadily decrease'), or 'noun + prepositional phrase' (e.g., 'a period of stagnation', 'on the cusp of change'). Using them demonstrates a sophisticated command of English.",
          "pt": "Colocações avançadas combinam adjetivos, advérbios ou substantivos com outras palavras para criar descrições específicas e diferenciadas de mudanças, tendências ou desenvolvimentos. Essas frases fixas ou semifixas são mais precisas e formais do que o vocabulário geral. Padrões comuns incluem 'adjetivo + substantivo' (por exemplo, 'mudança significativa', 'aumento drástico'), 'advérbio + verbo' (por exemplo, 'evoluir rapidamente', 'diminuir constantemente'), ou 'substantivo + frase preposicional' (por exemplo, 'um período de estagnação', 'na cúspide da mudança'). Usá-las demonstra um domínio sofisticado do inglês."
        },
        "mistakes": [
          {
            "en": "Using 'big change' instead of 'significant shift' or 'profound transformation'.",
            "pt": "Usar 'big change' em vez de 'significant shift' ou 'profound transformation'."
          },
          {
            "en": "Saying 'slow decrease' instead of 'gradual decline' or 'steady reduction'.",
            "pt": "Dizer 'slow decrease' em vez de 'gradual decline' ou 'steady reduction'."
          }
        ]
      }
    ],
