          "pt": "Trabalhe com um parceiro. Escolha duas sociedades – uma mais tradicional, outra mais moderna – e compare-as usando o vocabulário de 'Cultura e Sociedade' e colocações avançadas para descrever diferenças e mudanças. Discuta seus valores, costumes e quão diversas elas são. Esteja pronto para compartilhar suas descobertas."
