    "grammar": [
      {
        "title": {
          "en": "Discourse Markers for Hypothesizing and Speculating",
          "pt": "Marcadores Discursivos para Hipóteses e Especulação"
        },
        "examples": [
          {
            "en": "Presumably, the new policy will address the budget deficit. (Based on reasonable assumption)",
            "pt": "Presumivelmente, a nova política abordará o déficit orçamentário. (Baseado em suposição razoável)"
          },
          {
            "en": "Conceivably, artificial intelligence could personalize education for every student. (It's possible, though perhaps not definite)",
            "pt": "Concebivelmente, a inteligência artificial poderia personalizar a educação para cada aluno. (É possível, embora talvez não definitivo)"
          },
          {
            "en": "In all likelihood, the university will expand its online course offerings next year. (Highly probable)",
            "pt": "Com toda a probabilidade, a universidade expandirá suas ofertas de cursos online no próximo ano. (Altamente provável)"
          }
        ],
        "rule": {
          "en": "Discourse markers like 'presumably', 'conceivably', and 'in all likelihood' are used to introduce a hypothesis or speculation. They indicate the speaker's degree of certainty or the likelihood of an event or situation. 'Presumably' suggests something is probable based on available information. 'Conceivably' implies something is possible, even if unlikely. 'In all likelihood' signals a strong probability.",
          "pt": "Marcadores discursivos como 'presumably', 'conceivably' e 'in all likelihood' são usados para introduzir uma hipótese ou especulação. Eles indicam o grau de certeza do falante ou a probabilidade de um evento ou situação. 'Presumably' sugere que algo é provável com base nas informações disponíveis. 'Conceivably' implica que algo é possível, mesmo que improvável. 'In all likelihood' sinaliza uma alta probabilidade."
        },
        "mistakes": [
          {
            "en": "Incorrect usage with facts: 'Presumably, the sun rises in the east.' (Use for speculation, not known facts)",
            "pt": "Uso incorreto com fatos: 'Presumivelmente, o sol nasce no leste.' (Usar para especulação, não fatos conhecidos)"
          },
          {
            "en": "Overuse or mixing with definite statements: 'In all likelihood, I will definitely finish this assignment today.' (Avoid redundancy in certainty)",
            "pt": "Uso excessivo ou mistura com declarações definitivas: 'Com toda a probabilidade, eu definitivamente terminarei este trabalho hoje.' (Evitar redundância na certeza)"
          }
        ]
      }
    ],
