          "pt": "Imagine que você está liderando uma equipe para um novo projeto da empresa. Escreva uma breve proposta de projeto (150-200 palavras) para seus superiores, descrevendo os objetivos do projeto e como sua equipe garantirá uma colaboração eficaz, usando pelo menos três itens de vocabulário e duas expressões idiomáticas desta unidade. Inclua pelo menos uma frase de discussão acadêmica para introduzir um desafio."
