        "pt": "Você é um consultor encarregado de aconselhar uma empresa com uma nova equipe totalmente remota que está lutando com conexão e comunicação. Prepare uma apresentação ou discurso de 3-5 minutos, oferecendo estratégias baseadas no vocabulário (por exemplo, confiança, empatia, limites) e expressões idiomáticas (por exemplo, na mesma página, dar a sua parte) desta unidade. Incorpore pelo menos três frases de discussão acadêmica e conteúdo de revisão (phrasal verbs para negociação ou vocabulário de mídia noticiosa) para adicionar profundidade."
