          "who": "Carlos",
          "en": "Let me play devil's advocate for a moment. If we delve into traditional media, our budget might not stretch as far for digital, potentially reducing overall impact.",
          "pt": "Deixe-me bancar o advogado do diabo por um momento. Se nos aprofundarmos na mídia tradicional, nosso orçamento pode não ser suficiente para o digital, potencialmente reduzindo o impacto geral."
