    "grammar": [
      {
        "title": {
          "en": "Discourse Markers for Summarizing and Concluding Formally",
          "pt": "Marcadores Discursivos para Resumir e Concluir Formalmente"
        },
        "examples": [
          {
            "en": "The data shows a slight decrease in sales. In essence, our marketing strategy needs re-evaluation.",
            "pt": "Os dados mostram uma ligeira queda nas vendas. Em essência, nossa estratégia de marketing precisa ser reavaliada."
          },
          {
            "en": "We've discussed the budget, timelines, and team roles. To sum up, we're ready to proceed with the project launch.",
            "pt": "Discutimos o orçamento, os prazos e os papéis da equipe. Para resumir, estamos prontos para prosseguir com o lançamento do projeto."
          },
          {
            "en": "Many factors contribute to climate change, from industrial emissions to deforestation. Ultimately, collective global action is required to address this crisis.",
            "pt": "Muitos fatores contribuem para as mudanças climáticas, desde as emissões industriais até o desmatamento. Em última análise, uma ação global coletiva é necessária para enfrentar esta crise."
          }
        ],
        "rule": {
          "en": "Discourse markers like 'in essence,' 'to sum up,' and 'unfortunately' are used to formally summarize previous points or to deliver a final, definitive conclusion. They are often followed by a comma and appear at the beginning of a sentence. 'In essence' distills the core meaning, 'to sum up' provides a brief recap, and 'ultimately' expresses the final outcome or most important consideration.",
          "pt": "Marcadores discursivos como 'in essence', 'to sum up' e 'ultimately' são usados para resumir pontos anteriores formalmente ou para apresentar uma conclusão final e definitiva. Eles são frequentemente seguidos por uma vírgula e aparecem no início da frase. 'In essence' destila o significado central, 'to sum up' oferece uma breve recapitulação, e 'ultimately' expressa o resultado final ou a consideração mais importante."
        },
        "mistakes": [
          {
            "en": "Incorrect usage: 'In essence I think we should go.' (Too informal, often used to condense complex ideas.)",
            "pt": "Uso incorreto: 'In essence I think we should go.' (Muito informal, geralmente usado para condensar ideias complexas.)"
          },
          {
            "en": "Incorrect usage: 'We finished the meeting, ultimately.' (Should introduce a consequence or final point, not just mark completion.)",
            "pt": "Uso incorreto: 'We finished the meeting, ultimately.' (Deve introduzir uma consequência ou ponto final, não apenas marcar a conclusão.)"
          }
        ]
      }
    ],
