          "pt": "Maria: Estou um tanto hesitante em depender exclusivamente de agências de viagens online para reservas de grupo. Há mais do que isso; você precisa de supervisão pessoal para evitar problemas de última hora, especialmente com franquias de bagagem e mudanças de itinerário. É um pouco mais complicado do que parece garantir uma viagem tranquila para todos."
