          "en": "Idiomatic expressions add nuance and naturalness to statements of certainty or doubt. They often don't have literal meanings and convey a stronger sense of conviction or hesitation than simple adjectives.",
          "pt": "Expressões idiomáticas adicionam nuance e naturalidade às declarações de certeza ou dúvida. Elas frequentemente não têm significados literais e transmitem um senso mais forte de convicção ou hesitação do que adjetivos simples."
