          "pt": "Em pares, imagine que vocês são líderes de equipe negociando recursos para seus respectivos projetos comunitários baseados em hobbies (por exemplo, um workshop de fotografia versus uma iniciativa de jardinagem). Use expressões de certeza e dúvida para defender sua posição e frases de 'Liderança em Equipe' para buscar um consenso. Busquem uma resolução."
