          "pt": "Em grupos, discutam o papel dos hobbies no crescimento pessoal e desenvolvimento profissional. Compartilhem seus próprios hobbies e expressem certeza ou dúvida sobre o impacto deles em suas habilidades ou trajetória profissional. Usem 'Marcadores de discurso para resumir e concluir formalmente' (da Unidade 22) ao final da discussão."
