      "instruction": {
        "en": "Your task is to design a short (15-20 minute) team-building activity for a professional setting. The activity must incorporate an aspect of 'hobbies' and promote 'leadership teamwork'. Present your idea to another group, using idiomatic expressions to express certainty about its benefits and doubt about potential challenges. Be prepared to respond to counterarguments.",
        "pt": "Sua tarefa é projetar uma atividade de construção de equipe curta (15-20 minutos) para um ambiente profissional. A atividade deve incorporar um aspecto de 'hobbies' e promover 'liderança em equipe'. Apresente sua ideia a outro grupo, usando expressões idiomáticas para expressar certeza sobre seus benefícios e dúvida sobre possíveis desafios. Esteja preparado para responder a contra-argumentos."
      },
