          "en": "Good morning, everyone. Today, we're evaluating two different approaches for our upcoming marketing campaign. Option A suggests a strong digital focus, primarily through social media influencers and targeted ads. Meanwhile, Option B proposes a more traditional, event-based strategy with local sponsorships.",
          "pt": "Bom dia a todos. Hoje, estamos avaliando duas abordagens diferentes para nossa próxima campanha de marketing. A Opção A sugere um forte foco digital, principalmente através de influenciadores de mídia social e anúncios direcionados. Enquanto isso, a Opção B propõe uma estratégia mais tradicional, baseada em eventos, com patrocínios locais."
